"""An explicit prepare/review/confirm experience over signed server-owned tasks."""
TASK_CSS = r"""
.friday-task-panel{max-width:900px;margin:20px auto;padding:28px;border:1px solid var(--line);border-radius:24px;background:var(--panel);color:var(--ink)}
.friday-task-panel p{line-height:1.7;overflow-wrap:anywhere}.friday-task-panel blockquote{margin:12px 0;padding:14px;border-left:3px solid var(--blue);background:var(--panel2);border-radius:10px;overflow-wrap:anywhere}
.friday-task-state{display:inline-block;border-radius:20px;padding:8px 14px;background:var(--review-bg);color:var(--friday-review);font-size:12px;font-weight:700}
.friday-task-state[data-tone=live]{background:var(--live-bg);color:var(--friday-live)}.friday-task-state[data-tone=held]{background:var(--held-bg);color:var(--friday-held)}
.friday-task-panel h2{font-size:28px;letter-spacing:-.035em;line-height:1.25;margin:18px 0 12px}.friday-task-panel h3{font-size:16px;margin:0 0 10px}.friday-task-panel>p{max-width:68ch;color:var(--muted);font-size:14px}
.friday-task-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}.friday-task-detail{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:20px;border:1px solid var(--line);border-radius:16px;margin:20px 0;background:var(--panel2)}.friday-task-detail dt{color:var(--muted);font-size:12px}.friday-task-detail dd{margin:6px 0 0;overflow-wrap:anywhere;font-weight:650}
.friday-task-reason,.friday-task-draft,.friday-task-next{border:1px solid var(--line);border-radius:16px;padding:20px;margin:18px 0;background:var(--panel2)}.friday-task-reason ul{padding-left:20px;font-size:14px;line-height:1.8}.friday-task-finding{padding:16px 0;border-top:1px solid var(--line)}.friday-task-finding:first-of-type{border-top:0}.friday-task-finding small{color:var(--muted)}.friday-task-panel details{margin-top:22px;border-top:1px solid var(--line);padding-top:12px;font-size:13px}.friday-task-panel summary{cursor:pointer;min-height:44px;display:flex;align-items:center;color:var(--blue);font-weight:600}.friday-task-panel details p{color:var(--muted);font-size:12px}.friday-task-next p{margin-bottom:0;color:var(--muted)}.friday-task-draft small{display:block;color:var(--muted);margin-bottom:14px}.friday-copy-status{font-size:12px;color:var(--muted);margin:10px 0 0}
@media(max-width:600px){.friday-task-panel{padding:20px}.friday-task-detail{grid-template-columns:1fr}.friday-task-actions button{flex:1 1 180px}}
"""

TASK_JS = r"""
    {
      titles.assistant='Your next step. Prepared by Friday.';
      const taskView=view('assistant','Gemini prepares; independent checks decide what may proceed. Real money is not connected.');
      const taskPanel=element('section',null,'friday-task-panel');taskPanel.setAttribute('aria-live','polite');taskView.append(taskPanel);
      const taskPrepare=element('button','Prepare next step');taskPrepare.type='button';
      const taskTools=document.querySelector('.friday-chat-tools');const taskButtons=element('div',null,'friday-command-actions');const askButton=command.querySelector('button[type=submit]');taskButtons.append(askButton,taskPrepare);command.append(taskButtons);taskPrepare.className='friday-prepare-button';
      const taskHelp=element('p','Ask for an answer. Prepare for a checked plan or draft. Neither button pays.','friday-chat-status');taskTools.before(taskHelp);
      const consentLabel=document.querySelector('.friday-chat-consent');consentLabel.lastChild.textContent=' Include my saved inbox and artificial bills';
      let taskBusy=false;
      function taskError(text){taskPanel.replaceChildren(element('h2','We need to pause.'),element('p',text));const next=element('button','Review Activity');next.type='button';next.dataset.screenLink='activity';taskPanel.append(next);}
      function taskAmount(minor){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(minor/100);}
      function taskPresentation(task){
        if(task.expired)return {label:'Expired · prepare again',tone:'review',title:'This plan needs a fresh check.',next:'Return to Friday and prepare a new task. An expired plan cannot authorize a payment.'};
        const states={HOLD:{label:'On hold · no payment',tone:'held',title:'Paused before anything could move.',next:'Verify the quoted issue through a known official channel. Friday has not paid, refunded or frozen any real account.'},READY_FOR_CONFIRMATION:{label:'Prepared · not paid',tone:'live',title:'Your artificial payment is ready to review.',next:'Check the exact recipient and amount. Only your explicit confirmation starts the artificial-money payment.'},PREPARED_MESSAGE:{label:'Draft prepared · not sent',tone:'live',title:'Your verification message is ready.',next:'Copy this draft and send it through a provider contact you independently know is genuine.'},GUIDANCE_ONLY:{label:'Guidance · no payment',tone:'review',title:'Here is your next step.',next:'Use the guidance below. This is not proof that a financial request or recipient is legitimate.'}};
        return states[task.state]||{label:'Unknown outcome · review needed',tone:'review',title:'We cannot confirm this task.',next:'Return to Friday and prepare a new task. No successful payment is assumed.'};
      }
      function taskShow(task){
        if(task.scope!=='ARTIFICIAL_MONEY_ONLY'||task.signature_verified!==true||task.money_moved!==false)throw new Error('Unexpected task authority');
        taskPanel.replaceChildren();const present=taskPresentation(task);const badge=element('span',present.label,'friday-task-state');badge.dataset.state=task.state;badge.dataset.tone=present.tone;
        taskPanel.append(badge,element('h2',present.title),element('p',task.proposal.explanation));
        if(task.bill){const fields=element('dl',null,'friday-task-detail');[['Reference',task.bill.bill_reference],['Artificial amount',taskAmount(task.bill.amount_minor)],['Test provider',task.bill.provider_name],['Exact recipient',task.bill.payee_id]].forEach(([name,value])=>{const pair=element('div');pair.append(element('dt',name),element('dd',value));fields.append(pair);});taskPanel.append(fields);}
        if(task.gate_reasons.length||task.proposal.findings.length){const reasons=element('section',null,'friday-task-reason');reasons.append(element('h3','Why Friday paused'));const list=element('ul');task.gate_reasons.forEach(reason=>list.append(element('li',({SEMANTIC_RISK_REVIEW:'Gemini found a quoted risk indication. Verify before proceeding.',RELATED_CLAIM_REQUIRES_REVIEW:'Related documents report a conflict, missing detail or possible previous payment.',PROVIDER_CLAIM_CONFLICT:'Your document claims differ from the artificial provider record.',PAYMENT_NOT_ELIGIBLE:'The saved reserve, single-payment limit or bill status does not allow this task.',SANDBOX_SETUP_REQUIRED:'Save your artificial-money rules in My rules first, then prepare a new task. This does not connect a real bank.'}[reason]||'An additional independent check requires review: '+reason))));reasons.append(list);
        task.proposal.findings.forEach(finding=>{const item=element('article',null,'friday-task-finding');item.append(element('b',finding.kind.replaceAll('_',' ')),element('blockquote',finding.quote),element('p',finding.reason),element('small','Source: '+finding.source_id+' · potential risk, not a fraud verdict'));reasons.append(item);});taskPanel.append(reasons);}
        if(task.proposal.verification_message){const draft=element('section',null,'friday-task-draft');draft.append(element('h3','A message you can use'),element('blockquote',task.proposal.verification_message),element('small','Not sent. Use a provider contact you independently know is genuine.'));const copy=element('button','Copy verification message','planner');copy.type='button';const copyStatus=element('p',null,'friday-copy-status');copyStatus.setAttribute('role','status');copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(task.proposal.verification_message);copyStatus.textContent='Copied. Nothing has been sent.';}catch{copyStatus.textContent='Clipboard unavailable. Select and copy the message above.';}});draft.append(copy,copyStatus);taskPanel.append(draft);}
        const nextStep=element('section',null,'friday-task-next');nextStep.append(element('h3','What happens next'),element('p',present.next));taskPanel.append(nextStep);
        const actions=element('div',null,'friday-task-actions');
        if(task.gate_reasons.includes('SANDBOX_SETUP_REQUIRED')){const setup=element('button','Open My rules');setup.type='button';setup.dataset.screenLink='settings';actions.append(setup);}
        if(task.state==='READY_FOR_CONFIRMATION'&&!task.expired){const confirm=element('button','Confirm artificial payment','planner');confirm.type='button';confirm.addEventListener('click',async()=>{if(taskBusy)return;taskBusy=true;confirm.disabled=true;confirm.textContent='Rechecking evidence and running…';try{const outcome=await jsonRequest('/api/friday/tasks/'+task.task_id+'/confirm','POST',{expected_task_sha256:task.task_sha256,confirm_sandbox_execution:true});if(outcome.run?.run_id){await openRun(outcome.run.run_id);}else{taskError('No completed run was returned. Review Activity and any hold before proceeding.');}}catch(error){taskError('Confirmation is unavailable or the evidence changed. Check Activity before attempting another payment. No success is assumed.');}finally{taskBusy=false;}});actions.append(confirm);}
        const back=element('button','Ask Friday');back.type='button';back.dataset.screenLink='home';const evidence=element('button','Review financial inbox');evidence.type='button';evidence.dataset.screenLink='review';actions.append(back,evidence);taskPanel.append(actions);
        const details=element('details');details.append(element('summary','How this was checked · evidence & limits'),element('p',task.provenance.mode+' · '+task.provenance.model+' · '+task.provenance.model_calls+' planning call. Exact risk quotes checked; task signed by Friday, not by a bank.'),element('p','Valid until '+new Date(task.expires_at).toLocaleString()+'. Related evidence and rules are checked again before an eligible artificial payment.'),element('p',task.coverage.workspace_included?task.coverage.provider_records_sent+' artificial provider records and '+task.coverage.review_cases_sent+' inbox cases included. '+task.coverage.limits:'Request only. Your saved inbox, bills and financial rules were not included.'),element('p','Risk analysis can miss scams or raise false warnings. Preparation reads bounded snapshots, not every account or document. No verified real bank is connected.'));taskPanel.append(details);
      }
      async function prepareFridayTask(){const message=$('home-command').value.trim();const consent=$('friday-chat-workspace');if(message.length<5){toast('Enter what you want Friday to prepare.');return;}if(taskBusy)return;taskBusy=true;taskPrepare.disabled=true;show('assistant');taskPanel.replaceChildren(element('h2','Friday is preparing your next step…'),element('p','Understanding your request, checking quoted risks and binding the evidence. No payment is being performed.'));try{const task=await jsonRequest('/api/friday/tasks','POST',{message,include_workspace:consent.checked});taskShow(task);history.replaceState({},'','#task='+task.task_id);}catch(error){taskError('Live task preparation failed or the selected bill could not be grounded. No payment was submitted. For a saved bill, include your workspace; otherwise ask for a risk check or verification message.');}finally{taskBusy=false;taskPrepare.disabled=false;}}
      taskPrepare.addEventListener('click',prepareFridayTask);
      const beforeTaskShow=show;show=function(name,push=true){if(/^task=task_[a-f0-9]{32}$/.test(name)){beforeTaskShow('assistant',false);taskPanel.replaceChildren(element('p','Loading your saved task. No financial action is being performed.'));jsonRequest('/api/friday/tasks/'+name.slice(5),'GET').then(taskShow).catch(()=>taskError('This task cannot be opened in your workspace. Ask Friday to prepare a new task.'));return;}beforeTaskShow(name,push);};
    }
"""
